def bullets(xs): return '\n'.join('- ' + x for x in xs)

def patch(text, fname):
    out, pos = [], 0
    for m in re.finditer(r'^@@task ([^|]+)\|.*$', text, re.M):
        num = m.group(1).strip(); add = P.get((fname, num))
        out.append(text[pos:m.end()]); pos = m.end()
        if not add: continue
        # find this task's matching @@end (depth-aware)
        depth, i = 1, m.end()
        for mm in re.finditer(r'^(@@task|@@funnel|@@end)\b.*$', text[m.end():], re.M):
            depth += 1 if mm.group(1) != '@@end' else -1
            if depth == 0: i = m.end() + mm.start(); break
        body = text[m.end():i]
        if W in add and '#### Why it matters' not in body:
            body = '\n#### Why it matters\n' + add[W] + '\n' + body
        tail = ''
        if G in add and '#### What good looks like' not in body: tail += '\n#### What good looks like\n' + bullets(add[G]) + '\n'
        if M in add and '#### Common mistakes' not in body: tail += '\n#### Common mistakes\n' + bullets(add[M]) + '\n'
        out.append(body.rstrip('\n') + '\n' + tail); pos = i
    out.append(text[pos:])
    return ''.join(out)

for f in sorted(D.glob('*.md')):
    t = f.read_text(); n = patch(t, f.name)
    if n != t: f.write_text(n); print('patched', f.name)
